<div class="auth-card"><div class="auth-heading"><span class="eyebrow">Welcome back</span><h2>Sign in to your portal</h2><p>Applicants, students and authorised staff use the same secure sign-in.</p></div><form method="post" action="<?= url('login') ?>" class="auth-form"><?= csrf_field() ?><label><span>Email address</span><div class="input-with-icon"><i>@</i><input type="email" name="email" value="<?= e(old('email')) ?>" autocomplete="email" required autofocus placeholder="you@example.com"></div><?= error('email')?'<small class="field-error">'.e(error('email')).'</small>':'' ?></label><label><span class="label-row">Password <a href="<?= url('forgot-password') ?>">Forgot password?</a></span><div class="input-with-icon"><i>⌁</i><input type="password" name="password" autocomplete="current-password" required placeholder="Enter your password" data-password><button type="button" data-password-toggle aria-label="Show password">Show</button></div></label><label class="check-control"><input type="checkbox" name="remember" value="1"><span>Keep me signed in on this device</span></label><button class="button button-primary button-block" type="submit">Sign in securely →</button></form><div class="auth-divider"><span>New applicant?</span></div><a class="button button-outline button-block" href="<?= url('register') ?>">Create an applicant account</a><div class="security-note"><span>⌾</span><p><b>Your information is protected.</b> Sessions are secured, sensitive actions are logged and private files require permission.</p></div></div>
